entries[139773] = { ["name"] = "Banner des Mantisreiches", ["text"] = "Wirken in 2 sek.\nTrotz der mächtigen Magie, über die sie verfügen, bevorzugen die Mogu zur Errichtung gewaltiger Denkmäler häufig den Einsatz von Sklaven. Dieses Kassenbuch dokumentiert den Sklavenverschleiß bei der Errichtung eines solchen Denkmals." }
entries[139774] = { ["name"] = "Kosmischer Beschuss" }
entries[139775] = { ["name"] = "Banner des Mantisreiches" }
entries[139776] = { ["name"] = "Banner des Mantisreiches", ["text"] = "Wirken in 2 sek.\nObwohl die Mantis Windwolle und kaiserliche Seide verwenden, ist ihr bevorzugtes Material eine Art von \"Gewebe\", das aus den Flügeln verschiedener insektoider Kreaturen geschaffen wird - einschließlich ihrer eigenen. Dieses Banner ist ein Beispiel." }
entries[139777] = { ["name"] = "Steinschmettern", ["text"] = "25 Meter Reichweite\nWirken in 3 sek.\nBenötigt Nahkampfwaffe\nEin heftiger Überkopfangriff, der körperlichen Schaden verursacht und alle Gegner vor dem Zaubernden betäubt." }
entries[139778] = { ["name"] = "Statue Frozen Slam Prep" }
entries[139779] = { ["name"] = "Uralter Harzspender", ["text"] = "Wirken in 2 sek.\nDie Mantis bevorzugen es, das Kypariharz vor dem Verzehr reifen zu lassen. Dazu verwenden sie Vorrichtungen wie diese. An diesem uralten Exemplar könnt Ihr erkennen, dass sich ihr Entwurf im Laufe der Zeit nur unwesentlich verändert hat." }
entries[139780] = { ["name"] = "Die alte Gottesanbeterin", ["text"] = "Wirken in 2 sek.\nDiese Statue eines Klaxxi'va stammt in etwa aus der Zeit der Ankunft der Titanen. Um den Sockel der Statue ist ein Gebet an \"den Siebenköpfigen\" eingelassen. Das Wort \"Klaxxi\" bezeichnete in der alten Sprache einen Priester." }
entries[139781] = { ["name"] = "Inaktiver Schallsignalgeber", ["text"] = "Wirken in 2 sek.\nDie Technologie hinter den Schallsignalgebern der Mantis ist für alle anderen Völker undurchschaubar. Ihre Funktionalität scheint auf einem Teil der Mantisphysiologie zu beruhen. Dieses uralte Schallsignal ist – obwohl intakt – ohne einen Mantis als Anwender vollkommen unbrauchbar." }
entries[139782] = { ["name"] = "Überreste eines Getreuen", ["text"] = "Wirken in 2 sek.\nWie es scheint, ist der Konservierungsprozess in Bern nicht ohne Risiko. Nur der Kopf dieses Getreuen hat dem Zahn der Zeit standgehalten. Er scheint aus einer Zeit vor der Revolution der Pandaren zu stammen, das genaue Zeitalter zu bestimmen ist jedoch unmöglich." }
entries[139783] = { ["name"] = "Mantislampe", ["text"] = "Wirken in 2 sek.\nDas Leuchten dieser Lampe wird weder durch Feuer noch Magie erzeugt. In ihrem Inneren könnt Ihr viele leuchtende Insekten erkennen, die in Bern konserviert wurden." }
entries[139784] = { ["name"] = "Pollensammler", ["text"] = "Wirken in 2 sek.\nEs ist schwierig, den Zweck dieses Objekts zu bestimmen, es scheint jedoch eine Art Pollensammler zu sein." }
entries[139785] = { ["name"] = "Kypariharzbehälter", ["text"] = "Wirken in 2 sek.\nAuch wenn es nach Bern aussieht, ist dieser Behälter in der Tat aus Kunchongsekret gefertigt. Das Gleiche gilt für viele herkömmliche Einrichtungsgegenstände der Mantis." }
entries[139786] = { ["name"] = "Himmelshäscher der Mantis", ["text"] = "Wirken in 2 sek.\nDieses uralte \"Himmelshäscher\"-Schwert wurde für fliegende Mantis hergestellt: es ist extrem leicht und gut ausbalanciert, sodass es von einem herabstoßenden Angreifer leicht in weiten Bögen geschwungen werden kann. Die meisten Mantis werfen während ihres Übergangsritus in die Reihen der Erwachsenen ihre Flügel ab, als Zeichen stark genug zu sein um schwere Waffen und Rüstung zu tragen - daher ist es sehr selten, so feine Handwerkskunst in einer leichten Mantisklinge zu finden. Es ist wahrscheinlich, dass diese Waffe einst von einem Getreuen geführt wurde.\nHimmelshäscher der Mantis\nAccountgebunden\nEinhändig Schwert\n4,434 - 8,236 Schaden Tempo 2.60\n(2,437 Schaden pro Sekunde)\n+385 Stärke\n+578 Ausdauer\nErhöht Eure Tempowertung um + 257.\nErhöht Eure Meisterschaftswertung um + 257.\nHaltbarkeit 90 / 90\n85\n\"Die Einzelheiten dieses Artefakts wurden bereits in Eurem Archäologiebuch unter \"Restaurierte Artefakte\" protokolliert.\"" }
entries[139787] = { ["name"] = "Schallimpulsgenerator", ["text"] = "Wirken in 2 sek.\nMantis können ein wesentlich größeres Klangspektrum erzeugen und hören als andere sterbliche Völker. Ihr angeborener Hörsinn für extrem hohe und tiefe Frequenzen ermöglicht Mantis, Waffen wie diese herzustellen. Die von diesem Apparat erzeugten Schallimpulse können das Zellgewebe von Muskeln und Organe zerfetzen. Direkte Treffer können Innereien verflüssigen.\nSchallimpulsgenerator\nAccountgebunden\nDistanz Schusswaffe\n6,669 - 12,386 Schaden Tempo 2.90\n(3,285 Schaden pro Sekunde)\n+899 Beweglichkeit\n+1.349 Ausdauer\nErhöht Eure Tempowertung um + 600.\nErhöht Eure Meisterschaftswertung um + 600.\nHaltbarkeit 100 / 100\n85\n\"Die Einzelheiten dieses Artefakts wurden bereits in Eurem Archäologiebuch unter \"Restaurierte Artefakte\" protokolliert.\"" }
